// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, random } from '../remotionShim';


export type ComponentNameProps = Record<string, any>;

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#090A0F",
  transparentBackground = false,
  durationInSeconds = 10,
  silhouetteColor = "#1A1D27",
  energyColor = "#00F0FF",
  structureColor = "#FFFFFF",
  glowIntensity = 0.8,
  blueprintLayers = 7,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // ---------------------------------------------------------------------------
  // PARSER SAFETY & BASE CALCULATIONS
  // ---------------------------------------------------------------------------
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const durationFrames = durationInSeconds * fps;
  const baseSize = Math.min(width, height) * 0.7; // Optimize for 9:16 vertical dominance

  // ---------------------------------------------------------------------------
  // ANIMATION TIMING & SPRINGS
  // ---------------------------------------------------------------------------
  // Cinematic entrance spring
  const entranceProgress = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 40, mass: 1.5 },
  });

  // Slow, continuous camera push-in
  const cameraScale =
    entranceProgress *
    interpolate(frame, [0, durationFrames], [0.8, 1.15], {
      extrapolateRight: "clamp",
    });

  // Smooth cinematic camera pan (Y-axis rotation) and tilt (X-axis)
  const cameraYaw = interpolate(frame, [0, durationFrames], [-35, 25]);
  const cameraPitch = interpolate(frame, [0, durationFrames], [-10, 5]);
  const cameraLift = interpolate(entranceProgress, [0, 1], [150, 0]);

  // Dynamic blueprint expansion (extrusions pull out from the center)
  const layerSpacing = interpolate(entranceProgress, [0, 1], [0, 30]);

  // ---------------------------------------------------------------------------
  // SILHOUETTE SVG PATH (Minimalist, Athletic, Corporate)
  // ---------------------------------------------------------------------------
  const renderSilhouette = (isCenter: boolean, opacity: number) => {
    // A clean, broad-shouldered geometric bust
    const headPath = `M 150 110 A 45 45 0 1 0 150 20 A 45 45 0 1 0 150 110 Z`;
    const bodyPath = `M 150 150 C 95 150, 45 200, 35 290 Q 33 340 60 340 L 240 340 Q 267 340 265 290 C 255 200, 205 150, 150 150 Z`;

    return (
      <svg width={baseSize} height={baseSize} viewBox="0 0 300 400" style={{ overflow: "visible" }}>
        <defs>
          <filter id="glow">
            <feGaussianBlur stdDeviation={10 * glowIntensity} result="coloredBlur" />
            <feMerge>
              <feMergeNode in="coloredBlur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>
        <g opacity={opacity} filter={isCenter ? "none" : "url(#glow)"}>
          <path
            d={`${headPath} ${bodyPath}`}
            fill={isCenter ? silhouetteColor : "none"}
            stroke={isCenter ? "none" : energyColor}
            strokeWidth={isCenter ? 0 : 2}
            strokeDasharray={isCenter ? "none" : "15 10"}
            strokeDashoffset={isCenter ? 0 : -(frame * 1.5)}
          />
        </g>
      </svg>
    );
  };

  // ---------------------------------------------------------------------------
  // ORBITAL STRUCTURE COMPONENT (The "Training Plan" Building)
  // ---------------------------------------------------------------------------
  const Orbit = ({
    rx,
    ry,
    rzSpeed,
    sizeRatio,
    color,
    isDashed,
    delay,
    thickness,
  }: {
    rx: number;
    ry: number;
    rzSpeed: number;
    sizeRatio: number;
    color: string;
    isDashed: boolean;
    delay: number;
    thickness: number;
  }) => {
    const orbitSize = baseSize * sizeRatio;
    const progress = spring({
      frame: Math.max(0, frame - delay),
      fps,
      config: { damping: 20, stiffness: 60 },
    });
    
    // Continuous rotation
    const rz = frame * rzSpeed;
    const perimeter = orbitSize * Math.PI;
    const drawOffset = interpolate(progress, [0, 1], [perimeter, 0]);

    return (
      <div
        style={{
          position: "absolute",
          width: orbitSize,
          height: orbitSize,
          top: "50%",
          left: "50%",
          marginLeft: -orbitSize / 2,
          marginTop: -orbitSize / 2,
          transform: `rotateX(${rx}deg) rotateY(${ry}deg) rotateZ(${rz}deg)`,
          transformStyle: "preserve-3d",
        }}
      >
        <svg
          width={orbitSize}
          height={orbitSize}
          viewBox={`0 0 ${orbitSize} ${orbitSize}`}
          style={{ overflow: "visible" }}
        >
          {/* Main Ring */}
          <circle
            cx={orbitSize / 2}
            cy={orbitSize / 2}
            r={orbitSize / 2}
            fill="none"
            stroke={color}
            strokeWidth={thickness}
            strokeDasharray={isDashed ? "8 12" : perimeter}
            strokeDashoffset={isDashed ? -frame * 2 : drawOffset}
            opacity={progress * 0.7}
          />
          {/* Node / Tracker (Data Point) */}
          <circle
            cx={orbitSize}
            cy={orbitSize / 2}
            r={4 + thickness}
            fill={energyColor}
            opacity={progress}
            style={{
              transformOrigin: "50% 50%",
              transform: `rotate(${frame * (rzSpeed * 2)}deg)`,
            }}
          />
        </svg>
      </div>
    );
  };

  // ---------------------------------------------------------------------------
  // RENDER PHASE
  // ---------------------------------------------------------------------------
  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* Premium Background Vignette / Subtle Pulse */}
      <AbsoluteFill
        style={{
          background: `radial-gradient(circle at 50% 50%, ${energyColor}15 0%, ${bgColor} 70%)`,
          opacity: interpolate(entranceProgress, [0, 1], [0, 1]),
        }}
      />

      {/* 3D Scene Wrapper */}
      <AbsoluteFill
        style={{
          perspective: 1400,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        {/* Camera Rig */}
        <div
          style={{
            position: "relative",
            width: baseSize,
            height: baseSize,
            transformStyle: "preserve-3d",
            transform: `translateY(${cameraLift}px) scale(${cameraScale}) rotateX(${cameraPitch}deg) rotateY(${cameraYaw}deg)`,
          }}
        >
          {/* Data Rings / Architecture */}
          <Orbit rx={80} ry={0} rzSpeed={0.5} sizeRatio={1.4} color={structureColor} isDashed={false} delay={10} thickness={1} />
          <Orbit rx={70} ry={30} rzSpeed={-0.8} sizeRatio={1.6} color={energyColor} isDashed={true} delay={20} thickness={2} />
          <Orbit rx={70} ry={-45} rzSpeed={0.6} sizeRatio={1.2} color={structureColor} isDashed={true} delay={30} thickness={1} />
          <Orbit rx={0} ry={90} rzSpeed={1.2} sizeRatio={1.8} color={energyColor} isDashed={false} delay={40} thickness={0.5} />

          {/* Holographic Silhouette Blueprint Layers */}
          {Array.from({ length: blueprintLayers }).map((_, i) => {
            const isCenter = i === Math.floor(blueprintLayers / 2);
            // Center is solid, outer layers are wireframes fading out
            const offsetFromCenter = Math.abs(i - Math.floor(blueprintLayers / 2));
            const opacity = isCenter 
              ? 1 
              : interpolate(offsetFromCenter, [1, blueprintLayers / 2], [0.6, 0.05], { extrapolateRight: "clamp" });
            
            const zPosition = (i - Math.floor(blueprintLayers / 2)) * layerSpacing;

            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  top: "50%",
                  left: "50%",
                  marginLeft: -baseSize / 2,
                  marginTop: -baseSize / 2,
                  width: baseSize,
                  height: baseSize,
                  transform: `translateZ(${zPosition}px)`,
                  pointerEvents: "none",
                }}
              >
                {renderSilhouette(isCenter, opacity)}
              </div>
            );
          })}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default ComponentName;